WITH RECURSIVE x5 AS (SELECT -128 UNION SELECT x4.v2258 + 33 FROM x7) SELECT x4.v2258, x4.v2258, CONCAT_WS(REPEAT(CONCAT(x4.v2258 COLLATE utf8mb4_roman_ci), -1330441018), CONCAT_WS('', CONCAT(HEX(STRCMP('9', x4.v2258))), (x4.v2258 - INTERVAL '-1941528800' DAY_MINUTE))) AS x2, x4.v2258 FROM v2257 AS x4 WHERE EXISTS(SELECT * FROM x6 WHERE x4.v2258 <> x4.v2258)